    reg [15:0] t0;
    reg [15:0] t1;
    reg [15:0] t2;
    reg [15:0] t3;
    reg [15:0] t4;
    reg [15:0] t5;
    reg [15:0] t6;
    reg [15:0] t7;
    reg [15:0] t8;
    always @(posedge clk) begin
        if (!rst_n) begin y <= 16'd0; t0 <= 16'd0; t1 <= 16'd0; t2 <= 16'd0; t3 <= 16'd0; t4 <= 16'd0; t5 <= 16'd0; t6 <= 16'd0; t7 <= 16'd0; t8 <= 16'd0; end
        else begin
            t0 <= 16'd65;
            t1 <= t0 * x + 16'd30;
            t2 <= t1 * x + 16'd3;
            t3 <= t2 * x + 16'd97;
            t4 <= t3 * x + 16'd7;
            t5 <= t4 * x + 16'd99;
            t6 <= t5 * x + 16'd95;
            t7 <= t6 * x + 16'd42;
            t8 <= t7 * x + 16'd1;
            y <= t8;
        end
    end
endmodule

